(function(){"use strict";app.factory("politicaService",["$injector",function(t){const e=t.get("mainService"),n="Config/Politica/",o="Config/Acceso/",a={get:function(t){return e.getData("get",n+"?json="+JSON.stringify(t),null,!0).then(t=>{if("0"===t.code)throw t;if("1"===t.code){let e=JSON.parse(t.payload)||[];return e}})},save:function(t){return e.getData("post",`${n}?json=${JSON.stringify(t)}`,null,!0)},update:function(t,o){return e.getData("put",`${n}${t}?json=${JSON.stringify(o)}`,null,!0)},delete:function(t){return e.getData("delete",n+t,null,!0)},getAcceso:t=>e.getData("get",o+"?json="+JSON.stringify(t),null,!0).then(t=>{if("0"===t.code)throw t;if("1"===t.code){let e=JSON.parse(t.payload)||[];return e}}),updateAcceso:function(t){return e.getData("put",`${o}`,{data:{accesos:t}},!0)}};return a}])})(window.angular);